INSERT INTO "citation_mining" ("slug", "local_ref_id", "global_ref_id", "doi", "backward", "forward", "connections_produced", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "deferred_reason") VALUES ('accessible-circulation-geometry', '22', 'REF-00980', NULL, 1, 0, '[]', NULL, '2026-09-18 20:04', 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', '2026-09-18 20:04', 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', 'DEPTH-1 DEFERRAL (citation-miner section 6). Discovered by this batch pass over REF-00985; mining it here is hop 2. Expected yield is MODEST AND SHOULD BE SAID SO NOW rather than discovered later: a 1997 paper cites pre-1997 work, and the ramp-slope empirical literature before that date is exactly what REF-01002 abstract calls limited. Rank it below REF-01002 and REF-00979.');
INSERT INTO "citation_mining" ("slug", "local_ref_id", "global_ref_id", "doi", "backward", "forward", "connections_produced", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "deferred_reason") VALUES ('accessible-circulation-geometry', '23', 'REF-00979', NULL, 1, 0, '[]', NULL, '2026-09-18 20:04', 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', '2026-09-18 20:04', 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', 'DEPTH-1 DEFERRAL (citation-miner section 6). Discovered by this batch pass over REF-00985; hop 2. Ranks SECOND of the three new deferrals on the predictor GAP-018 sets out for prospective testing: Chow et al. measure propulsion across a slope series, so by that hypothesis they cite the propulsion-on-slopes literature -- the same reasoning that made REF-00985 the productive anchor of this batch. Mining it is therefore also a TEST of GAP-018 hypothesis, and the prediction is recorded here before the pass so the test is real.');
INSERT INTO "citation_mining" ("slug", "local_ref_id", "global_ref_id", "doi", "backward", "forward", "connections_produced", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "deferred_reason") VALUES ('accessible-circulation-geometry', '24', 'REF-01002', NULL, 1, 0, '[]', NULL, '2026-09-18 20:04', 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', '2026-09-18 20:04', 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', 'DEPTH-1 DEFERRAL, AND IT IS THE DESIGN RATHER THAN CAPACITY. citation-miner section 6 is a hard constraint -- mine references OF an anchor, never references of what that pass DISCOVERED, in the same pass. REF-01002 was discovered by this batch backward pass over REF-00977; mining it here would be hop 2. IT IS ALSO THE HIGHEST-VALUE DEFERRAL ON THE SLUG and should lead the next pass: a 2009 study whose own framing says design recommendations for either the running slope or the cross slope requirements are based on limited empirical research cites whatever empirical work existed, and that is the thinnest, most directly relevant seam this parameter has. NOTE THE OBSTACLE BEFORE STARTING: no DOI, so there is
UPDATE "citation_mining" SET "connections_produced" = '["REF-01002"]', "notes" = 'BACKWARD PASS EXECUTED. 117 deposited reference entries, 81 with DOIs, 6 passing the ramp/slope/gradient/barrier screen. THE DEFERRAL REASON IS CORRECTED, NOT JUST DISCHARGED: batch 15 deferred this on a Taylor & Francis 403 plus a refused repository copy -- that is FULL-TEXT inaccessibility, and backward mining never needed the full text. The deposited reference list is the object and it was free. That generalises to every paywalled anchor this corpus will meet. YIELD: the one real find carries NO DOI in the deposit (Vredenburgh et al. 2009), so it was invisible to any DOI-keyed screen and had to be resolved by title -- admitted REF-01002, the only stated maximum for this parameter at an anchoring tier. Depth-1: nothing discovered here is itself mined. Full screening record: search_executions exec 68.

DEFERRAL DISCHARGED 2026-09-18 20:00 by session_2026-09-18-research-batch-16-backward-mining-t2-anchors. It read: BACKWARD PASS DEFERRED, AND THE REASON IS SPECIFIC RATHER THAN CAPACITY. REF-00977''s backward set IS its 48 included studies, which is the richest single unmined seam now in the corpus for this parameter: a systematic review''s reference list is pre-screened primary work on exactly this subject. It cannot be mined from the abstract, and the full text is behind Taylor & Francis (HTTP 403 this session; the Nottingham repository copy also refused). Owed, named, and the highest-value backward target available.', "updated_at" = '2026-09-18 20:00', "updated_by_session" = 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', "deferred_reason" = NULL WHERE "slug" = 'accessible-circulation-geometry' AND "local_ref_id" = '19';
UPDATE "citation_mining" SET "connections_produced" = '["REF-00980", "REF-00979"]', "notes" = 'BACKWARD PASS EXECUTED AND IT CARRIED THE BATCH. 46 reference entries, 36 with DOIs, 23 matching the screen -- against a deferral note ranking this LOWEST of three and my own recorded prior of zero. Both rankings inverted, and the reason was derivable in advance: a biomechanics paper measuring propulsion effort cites the propulsion-on-slopes literature. Produced REF-00980 (Sanford 1997, the 171-subject test of the ADA-permitted range) and REF-00979 (Chow 2009, the 4-to-10-degree inflection band), both cross-filed to RETIRED tombstone identifiers from the 2026-09-13 clear rather than re-minted. Depth-1 enforced. Full screening record: search_executions exec 70.

DEFERRAL DISCHARGED 2026-09-18 20:00 by session_2026-09-18-research-batch-16-backward-mining-t2-anchors. It read: backward mining deferred to the next pass: REF-00985 is the only EXACT-population anchor in this batch and its reference list is the highest-value target, but mining it properly is a depth-2 pass and this batch is depth-1 by design', "updated_at" = '2026-09-18 20:00', "updated_by_session" = 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', "deferred_reason" = NULL WHERE "slug" = 'accessible-circulation-geometry' AND "local_ref_id" = '3';
UPDATE "citation_mining" SET "notes" = 'BACKWARD PASS EXECUTED, ZERO YIELD, AND THE DEFERRAL NOTE NAMING THIS THE HIGHEST-VALUE TARGET IS REFUTED. 38 reference entries, 28 with DOIs, ZERO matching the ramp/slope/incline/gradient screen. A 2003 systematic review of wheelchair SKILLS TESTS cites the instrument-validation literature -- reliability, scoring, construct validity -- not the environmental-parameter literature. My own prior was wrong one layer further in: I predicted test-apparatus numbers needing a guard against over-reading, and there is nothing of the kind to over-read. RECORDED SO THE NEXT SESSION DOES NOT RE-QUEUE IT. This row is the first executed-but-zero-yield mining pass the CLI could express: until this session log-mining offered only --deferred-reason for it, which R6 forbids. Full screening record: search_executions exec 69.

DEFERRAL DISCHARGED 2026-09-18 20:00 by session_2026-09-18-research-batch-16-backward-mining-t2-anchors. It read: HIGHEST-VALUE TARGET IN THIS BATCH AND DELIBERATELY DEFERRED, NOT SKIPPED. A systematic review of 24 wheelchair skills tests carries a reference list of primaries, and ''ascending slopes'' is among its most frequently included tasks, so its references are the likeliest place a stated gradient exists. Mining it is a depth-2 pass; this batch is depth-1 by design (R2). Named here so the next pass starts with it.', "updated_at" = '2026-09-18 20:00', "updated_by_session" = 'session_2026-09-18-research-batch-16-backward-mining-t2-anchors', "deferred_reason" = NULL WHERE "slug" = 'accessible-circulation-geometry' AND "local_ref_id" = '4';

